mapper.select:
/* SmsUserRegistMapper.getUserIdByDi */
SELECT  USER_ID
FROM    TB_CM_SMS_USER_REGIST
WHERE   DI = #{di}

mapper.insert:
/* SmsUserRegistMapper.insertUserRegist */
INSERT INTO TB_CM_SMS_USER_REGIST
(
    USER_ID
,   DI
,   TEL_NO
,   AGREE1_YN
,   AGREE2_YN
,   REG_DT
,   REG_ID
,   MOD_DT
,   MOD_ID
)
VALUES
(
    #{userId}
,   #{di}
,   SBPENC.E(#{telNo})
,   'Y'
,   'Y'
,   #{regDt}
,   #{regId}
,   #{modDt}
,   #{modId}
)

mapper.delete:
/* SmsUserRegistMapper.deleteUserRegist */
DELETE  TB_CM_SMS_USER_REGIST
WHERE   1=1
AND     USER_ID = #{userId}

mapper.update:
/* SmsUserRegistMapper.deleteSmsTelNoManage */
UPDATE  HCS_SENDM_T C
SET     USE_YN  =   #{useYn}
,       MOD_DT  =   #{modDt}
,       MOD_ID  =   #{modId}
WHERE   EXISTS  (
                    SELECT  1
                    FROM    TB_CM_SMS_USER_REGIST A
                    ,       TB_CM_ADD_SMS_NO B
                    WHERE   B.USER_ID           =   A.USER_ID
                    AND     B.ORGN_CD           =   C.OGN_CD
                    AND     SBPENC.D(B.TEL_NO)  =   SBPENC.D(C.TEL_NO)
                    AND     B.CERT_ID           =   C.CERT_ID
                    AND     A.USER_ID           =   #{userId}
                )
